#!/usr/bin/env bash
# hassette: rerun jscpd default + weak with generated ("Do not edit this file directly") files excluded.
F="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
J="${JSCPD:-jscpd}"
O=${OUT:-$F/results}/hassette
H="${HASSETTE:?set HASSETTE to a hassette checkout}"
G="${GATE_CLUSTERS:?set GATE_CLUSTERS to the PMD gate cluster listing (cpd-plain.txt)}"
cd "$H" || exit 1
grep -l "Do not edit this file directly" $(cat "$O/all.txt") >"$O/generated.txt"
echo "generated files: $(wc -l <"$O/generated.txt")"; cat "$O/generated.txt"
grep -vxF -f "$O/generated.txt" "$O/all.txt" >"$O/all-nogen.txt"
python3 -I -c 'import json,sys; print(json.dumps({"path": [sys.argv[2] + "/" + l.strip() for l in open(sys.argv[1]) if l.strip()]}))' "$O/all-nogen.txt" "$H" >"$O/jscpd-paths-nogen.json"
cd /tmp || exit 1
for m in mild weak; do
  mkdir -p "$O/nogen-$m"
  "$J" -c "$O/jscpd-paths-nogen.json" --no-gitignore --absolute --mode $m --reporters json,silent --output "$O/nogen-$m" --no-tips >/dev/null 2>&1
  echo "== nogen mode=$m"
  python3 -I "$F/scripts/clusters.py" "$O/nogen-$m/jscpd-report.json" --root "$H/" | head -5
  python3 -I "$F/scripts/clusters.py" "$O/nogen-$m/jscpd-report.json" --root "$H/" --list >"$O/clusters-nogen-$m.txt"
  python3 -I "$F/scripts/compare_gate.py" "$G" "$O/nogen-$m/jscpd-report.json" "$H/"
done
